    Bucket='my-payload-bucket',
    Key='message-12345',
    Body=json.dumps(large_message)
)

# Send reference in SQS
sqs.send_message(
    QueueUrl=queue_url,
    MessageBody=json.dumps({
        's3_bucket': 'my-payload-bucket',
